function validate([text, first, second]) {
  if (typeof text !== 'string' || text.length < 1 || text.length > 1000) return 'text has 1 to 1000 characters.';
  if (!/^[a-z]+( [a-z]+)*$/.test(text)) return 'text is lowercase words separated by single spaces, with no space at either end.';
  for (const word of [first, second]) {
    if (typeof word !== 'string' || !/^[a-z]{1,10}$/.test(word)) return 'first and second are 1 to 10 lowercase letters.';
  }
  return null;
}

