function findOcurrences(text, first, second) {
  const padded = ' ' + text + ' ';
  const pattern = ' ' + first + ' ' + second + ' ';
  const found = [];
  let at = padded.indexOf(pattern);
  while (at !== -1) {
    const start = at + pattern.length;
    const end = padded.indexOf(' ', start);
    if (end > start) found.push(padded.slice(start, end));
    at = padded.indexOf(pattern, at + 1);
  }
  return found;
}

