function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const pools = [['a', 'b'], ['we', 'will', 'rock'], ['a', 'ab', 'b', 'ba'], ['x', 'y', 'xy', 'z']];
  const vocab = pools[pick(pools.length)];
  const words = [];
  if (size === 'large') {
    let length = -1;
    for (;;) {
      const word = vocab[pick(vocab.length)];
      if (length + 1 + word.length > 1000) break;
      words.push(word);
      length += 1 + word.length;
    }
  } else {
    const count = 1 + pick(10);
    for (let i = 0; i < count; i++) words.push(vocab[pick(vocab.length)]);
  }
  const choose = () => rand() < 0.85 ? vocab[pick(vocab.length)] : 'q'.repeat(1 + pick(3));
  return [words.join(' '), choose(), choose()];
}
